/// Returns true iff `v` starts with prefix `p` under the given definition:
/// - Always true if `p` is empty
/// - Otherwise `v.len() >= p.len()` and all characters match up to `p.len()`.
fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    if p.is_empty() {
        return true;
    }
    if v.len() < p.len() {
        return false;
    }
    for i in 0..p.len() {
        if v[i] != p[i] {
            return false;
        }
    }
    true
}

/// Filters `xs`, keeping exactly those sequences that start with `p`.
/// The relative order of kept sequences is preserved.
fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    // Borrow `p` during the scan; we can move matching sequences into the result.
    let mut out: Vec<Vec<char>> = Vec::new();
    for v in xs.into_iter() {
        if has_prefix(&v, &p) {
            out.push(v);
        }
    }
    out
}

